from threetears.evals import Eval

from fines import Loan, fine, load_closures

CLOSURES = load_closures("data/closures.jsonl")


def charge(case):
    """The fine for the returned loan."""
    return {"fine": fine(Loan.from_row(case), CLOSURES)}


def matches_old_system(case, out):
    """The loan is fined what the old system charged."""
    return out["fine"] == case["fine_pence"]

returns = Eval("data/returns.jsonl", runner=charge, grader=[matches_old_system], k=1)
